import React, { useEffect, useState } from "react";
import Sidebar from "../components/Sidebar";
import TopBar from "../components/TopBar";
import toast from "react-hot-toast";
import axios from "../utils/axios";
import { useNavigate } from "react-router-dom";

const Profile = () => {
  const [avatar, setAvatar] = useState("https://i.pravatar.cc/150?img=10");
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [editMode, setEditMode] = useState(false);
  const [showPasswordForm, setShowPasswordForm] = useState(false);
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  const navigate = useNavigate();
  const userId = localStorage.getItem("userId");

  useEffect(() => {
    if (!userId) {
      toast.error("Please log in first.");
      navigate("/login");
      return;
    }

    // Load from localStorage first for immediate display
    setName(localStorage.getItem("name") || "");
    setEmail(localStorage.getItem("email") || "");

    const fetchUser = async () => {
      try {
        // Correct path: /api/users/{id}
        const res = await axios.get(`/api/users/${userId}`);
        const user = res.data;
        setName(user.name || "");
        setEmail(user.email || "");
        localStorage.setItem("name", user.name || "");
        localStorage.setItem("email", user.email || "");
      } catch (err) {
        console.error("Failed to fetch user profile", err);
        // Don't navigate away - localStorage values still shown
      }
    };

    fetchUser();
  }, [userId, navigate]);

  const handleSave = async () => {
    try {
      await axios.put(`/api/users/${userId}`, { name, email });
      localStorage.setItem("name", name);
      localStorage.setItem("email", email);
      toast.success("Profile updated!");
      setEditMode(false);
    } catch (err) {
      console.error(err);
      toast.error("Failed to update profile");
    }
  };

  const handleAvatarChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      setAvatar(reader.result);
      toast.success("Profile picture updated!");
    };
    reader.readAsDataURL(file);
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  const handlePasswordUpdate = () => {
    if (newPassword.length < 6) {
      toast.error("Password must be at least 6 characters");
      return;
    }
    if (newPassword !== confirmPassword) {
      toast.error("Passwords do not match");
      return;
    }
    // Password update endpoint not yet in backend — show info message
    toast("Password change is not yet enabled in this version.", { icon: "ℹ️" });
    setNewPassword("");
    setConfirmPassword("");
    setShowPasswordForm(false);
  };

  return (
    <div className="flex">
      <Sidebar />
      <div className="flex-1">
        <TopBar />
        <div className="p-6 ml-0 md:ml-64 max-w-4xl">
          <h1 className="text-3xl font-bold text-gray-800 mb-6">My Profile</h1>

          <div className="bg-white rounded-xl shadow-md p-6 flex flex-col sm:flex-row gap-6">
            {/* Avatar */}
            <div className="flex flex-col items-center gap-3">
              <img
                src={avatar}
                alt="User avatar"
                className="w-24 h-24 rounded-full border border-gray-300 shadow-md object-cover"
              />
              <label
                htmlFor="avatar-upload"
                className="cursor-pointer bg-indigo-500 text-white text-sm px-4 py-1.5 rounded hover:bg-indigo-600 transition"
              >
                Change Photo
              </label>
              <input
                id="avatar-upload"
                type="file"
                accept="image/*"
                onChange={handleAvatarChange}
                className="hidden"
              />
            </div>

            {/* Fields */}
            <div className="flex-1 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
                <input
                  type="text"
                  value={name}
                  disabled={!editMode}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md bg-gray-100 text-gray-700 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
                <input
                  type="email"
                  value={email}
                  disabled={!editMode}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md bg-gray-100 text-gray-700 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div className="flex gap-2 pt-2">
                {editMode ? (
                  <>
                    <button
                      onClick={handleSave}
                      className="bg-indigo-600 text-white px-4 py-2 rounded hover:bg-indigo-700 transition"
                    >
                      Save Changes
                    </button>
                    <button
                      onClick={() => setEditMode(false)}
                      className="text-gray-500 hover:text-gray-700"
                    >
                      Cancel
                    </button>
                  </>
                ) : (
                  <button
                    onClick={() => setEditMode(true)}
                    className="bg-indigo-500 text-white px-4 py-2 rounded hover:bg-indigo-600 transition"
                  >
                    Edit Profile
                  </button>
                )}
              </div>

              <div className="pt-2">
                <button
                  onClick={() => setShowPasswordForm((prev) => !prev)}
                  className="text-indigo-600 font-medium text-sm hover:underline"
                >
                  {showPasswordForm ? "Cancel Password Change" : "Change Password"}
                </button>
              </div>

              {showPasswordForm && (
                <div className="space-y-3 pt-2">
                  <div>
                    <label className="block text-sm font-medium text-gray-700">New Password</label>
                    <input
                      type="password"
                      value={newPassword}
                      onChange={(e) => setNewPassword(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Confirm Password</label>
                    <input
                      type="password"
                      value={confirmPassword}
                      onChange={(e) => setConfirmPassword(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    />
                  </div>
                  <button
                    onClick={handlePasswordUpdate}
                    className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition"
                  >
                    Save New Password
                  </button>
                </div>
              )}

              <div className="pt-4 border-t mt-4">
                <button
                  onClick={handleLogout}
                  className="text-red-500 font-medium text-sm hover:underline"
                >
                  Log out
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Profile;
